                    normalized[word] = normal(word)
                for canonical, factor in normalized[word].items():
                    polynomial[canonical] = polynomial.get(canonical, 0) + coefficient * factor
        for word, coefficient in polynomial.items():
            if coefficient:
                incidence.setdefault(word, []).append((i, coefficient))
    words = list(incidence)
    if not words:
        return {}
    columns = [incidence[word] for word in words]
    compiled = monomial_map({'words': words, 'cache': payload['cache']})
    pair_weights = {}
    result = {}
    for word, row in compiled.items():
        middle = len(word) // 2
        partner = tuple((1, mode) for flag, mode in word[middle:]) + tuple((0, mode) for flag, mode in word[:middle])
        if word > partner:
            continue
        target = {}
        for pair, factor in row.items():
            factor = int(factor)
            if not factor:
                continue
            if pair not in pair_weights:
                a, b = pair
                left = columns[a]
                weights = {}
                if a == b:
                    for p, item in enumerate(left):
                        i, x = item
                        weights[(i, i)] = x * x
                        for q in range(p + 1, len(left)):
                            j, y = left[q]
                            weights[(i, j)] = 2 * x * y
                else:
                    for i, x in left:
                        for j, y in columns[b]:
                            coordinate = (i, j) if i <= j else (j, i)
                            weights[coordinate] = weights.get(coordinate, 0) + x * y
                pair_weights[pair] = {coordinate: weight for coordinate, weight in weights.items() if weight}
            weights = pair_weights[pair]
            if not target:
                if factor == 1:
                    target = weights.copy()
                else:
                    target = {coordinate: factor * weight for coordinate, weight in weights.items()}
            else:
                for coordinate, weight in weights.items():
                    target[coordinate] = target.get(coordinate, 0) + factor * weight
        if len(row) > 1:
            target = {coordinate: coefficient for coordinate, coefficient in target.items() if coefficient}
        if target:
            result[word] = target
            if partner != word:
                result[partner] = target.copy()
    return result
